      'cs.importCsv':'+ Import CSV','cs.csvTitle':'Import cameras from CSV','cs.csvIntro':'Download the template → fill in camera details → upload to add many at once · routes to a Site (edge) · cameras go online immediately','cs.csvDownloadTpl':'Download template','cs.csvChooseFile':'Choose CSV file','cs.csvPassWarn':'⚠ The CSV stores passwords in plain text — keep/delete the file carefully','cs.csvImportBtn':'Import cameras','cs.csvColType':'Type','cs.csvColStatus':'Status','cs.csvEmpty':'File is empty or has no data rows','cs.csvErrId':'missing camera_id','cs.csvErrVendor':'invalid vendor','cs.csvErrIp':'invalid ip','cs.csvErrSite':'unknown site','cs.csvErrDup':'duplicate camera_id','cs.csvSummary':'{ok} ready · {bad} skipped','cs.csvImportN':'Import {n} cameras','cs.csvImporting':'Importing…','cs.csvDone':'Imported {n} cameras','cs.csvSkippedN':'{n} skipped','cs.csvFail':'Import failed','cs.csvExample':'example (not imported)','cs.csvGuideTitle':'ℹ️ What goes in each column','cs.csvGuideExtraTitle':'▸ Advanced values (nvr_channel · capture_categories)','cs.csvGuideHtml':'<table style="width:100%;border-collapse:collapse;font-size:11px;margin-top:6px"><thead><tr style="text-align:left;color:var(--text-secondary)"><th style="padding:3px 6px">Column</th><th style="padding:3px 6px">Req</th><th style="padding:3px 6px">Accepts</th></tr></thead><tbody><tr><td style="padding:3px 6px"><code>camera_id</code></td><td style="padding:3px 6px">✓</td><td style="padding:3px 6px">letters/digits/- unique · starts with # = example, not imported</td></tr><tr><td style="padding:3px 6px"><code>vendor</code></td><td style="padding:3px 6px">✓</td><td style="padding:3px 6px">bosch · hikvision · dahua · onvif</td></tr><tr><td style="padding:3px 6px"><code>ip_address</code></td><td style="padding:3px 6px">✓</td><td style="padding:3px 6px">IPv4 e.g. 172.17.22.30</td></tr><tr><td style="padding:3px 6px"><code>site</code></td><td style="padding:3px 6px">✓</td><td style="padding:3px 6px">site code or name (e.g. hdy / หาดใหญ่)</td></tr><tr><td style="padding:3px 6px"><code>camera_name</code></td><td style="padding:3px 6px"></td><td style="padding:3px 6px">text (blank = use camera_id)</td></tr><tr><td style="padding:3px 6px"><code>cam_role</code></td><td style="padding:3px 6px"></td><td style="padding:3px 6px">standard · face · lpr (blank = standard)</td></tr><tr><td style="padding:3px 6px"><code>username / password</code></td><td style="padding:3px 6px"></td><td style="padding:3px 6px">text (password encrypted on edge push)</td></tr><tr><td style="padding:3px 6px"><code>http_port</code></td><td style="padding:3px 6px"></td><td style="padding:3px 6px">number (blank = 80)</td></tr><tr><td style="padding:3px 6px"><code>capture_categories</code></td><td style="padding:3px 6px"></td><td style="padding:3px 6px">face;anpr;vehicle;nonmotor;person;rule (; separated)</td></tr><tr><td style="padding:3px 6px"><code>location</code></td><td style="padding:3px 6px"></td><td style="padding:3px 6px">text</td></tr><tr><td style="padding:3px 6px"><code>latitude / longitude</code></td><td style="padding:3px 6px"></td><td style="padding:3px 6px">decimal (map coords)</td></tr><tr><td style="padding:3px 6px"><code>nvr_channel</code></td><td style="padding:3px 6px"></td><td style="padding:3px 6px">number 0-based (NVR channels only)</td></tr><tr><td style="padding:3px 6px"><code>notes</code></td><td style="padding:3px 6px"></td><td style="padding:3px 6px">text</td></tr></tbody></table>','cs.csvGuideExtra':'<div style="font-weight:600;font-size:11px;margin:6px 0 4px">nvr_channel — NVR channel (0-based)</div><table style="width:100%;border-collapse:collapse;font-size:11px"><thead><tr style="text-align:left;color:var(--text-secondary)"><th style="padding:3px 6px">nvr_channel</th><th style="padding:3px 6px">Dahua CGI</th><th style="padding:3px 6px">Physical</th></tr></thead><tbody><tr><td style="padding:3px 6px"><code>0</code></td><td style="padding:3px 6px">channel 1</td><td style="padding:3px 6px">channel 1</td></tr><tr><td style="padding:3px 6px"><code>1</code></td><td style="padding:3px 6px">channel 2</td><td style="padding:3px 6px">channel 2</td></tr><tr><td style="padding:3px 6px">blank</td><td style="padding:3px 6px">channel 1</td><td style="padding:3px 6px">standalone (not an NVR)</td></tr></tbody></table><div style="color:var(--text-secondary);font-size:10px;margin:2px 0 0">NVR channels = same NVR IP on every row + a different nvr_channel per channel</div><div style="font-weight:600;font-size:11px;margin:10px 0 4px">capture_categories — examples by use case</div><table style="width:100%;border-collapse:collapse;font-size:11px"><thead><tr style="text-align:left;color:var(--text-secondary)"><th style="padding:3px 6px">Use case</th><th style="padding:3px 6px">Value</th></tr></thead><tbody><tr><td style="padding:3px 6px">Face only</td><td style="padding:3px 6px"><code>face</code></td></tr><tr><td style="padding:3px 6px">Face + person (appearance)</td><td style="padding:3px 6px"><code>face;person</code></td></tr><tr><td style="padding:3px 6px">ANPR cars + bikes</td><td style="padding:3px 6px"><code>anpr;vehicle;nonmotor</code></td></tr><tr><td style="padding:3px 6px">ANPR motorbike lane</td><td style="padding:3px 6px"><code>anpr;nonmotor</code></td></tr><tr><td style="padding:3px 6px">People count + tripwire/region</td><td style="padding:3px 6px"><code>person;rule</code></td></tr><tr><td style="padding:3px 6px">IVS only</td><td style="padding:3px 6px"><code>rule</code></td></tr><tr><td style="padding:3px 6px">All vehicles</td><td style="padding:3px 6px"><code>vehicle;nonmotor</code></td></tr><tr><td style="padding:3px 6px">Capture everything</td><td style="padding:3px 6px">leave blank</td></tr></tbody></table><div style="font-weight:600;font-size:11px;margin:10px 0 4px">capture_categories — valid values (Dahua)</div><table style="width:100%;border-collapse:collapse;font-size:11px"><thead><tr style="text-align:left;color:var(--text-secondary)"><th style="padding:3px 6px">Value</th><th style="padding:3px 6px">Meaning</th></tr></thead><tbody><tr><td style="padding:3px 6px"><code>face</code></td><td style="padding:3px 6px">face detect/recognize</td></tr><tr><td style="padding:3px 6px"><code>anpr</code></td><td style="padding:3px 6px">license plate (LPR)</td></tr><tr><td style="padding:3px 6px"><code>vehicle</code></td><td style="padding:3px 6px">cars</td></tr><tr><td style="padding:3px 6px"><code>nonmotor</code></td><td style="padding:3px 6px">bicycle/motorbike</td></tr><tr><td style="padding:3px 6px"><code>person</code></td><td style="padding:3px 6px">person / appearance</td></tr><tr><td style="padding:3px 6px"><code>rule</code></td><td style="padding:3px 6px">IVS (line/region/left-taken/blind)</td></tr></tbody></table>',
